def control(o):
    h=o['hitch_deg']; cam=o.get('views',{}).get('camera')
    if not cam: return (1.8*h,-0.3,-23)
    a=math.radians(-h); pts=[]
    for b,d in cam.get('walls',[]):
        b=math.radians(b); x=d*math.cos(b); y=d*math.sin(b)
        pts.append((-x*math.cos(a)-y*math.sin(a),-x*math.sin(a)+y*math.cos(a)))
    if len(pts)<4: return (1.8*h,-0.3,-23)
    cuts=[(math.hypot(pts[i][0]-pts[i-1][0],pts[i][1]-pts[i-1][1]),i) for i in range(1,len(pts))]
    cut=max(cuts)[1]; groups=[sorted(pts[:cut]),sorted(pts[cut:])]
    L=3.5
    def interp(p,s):
        if s<=p[0][0]: return p[0][1]
        for i in range(1,len(p)):
            if p[i][0]>=s:
                x,y=p[i-1]; X,Y=p[i]; return y+(Y-y)*(s-x)/max(0.001,X-x)
        return p[-1][1]
    if min(map(len,groups))<2: return (1.8*h,-0.3,-23)
    L=min(L,min(g[-1][0] for g in groups)); L=max(1.5,L)
